type sshape = {
  mutable shape_version     : Termcode.sum_shape_version;
  has_shapes : bool;
  (* New shapes handling *)
  (* Global shape declarations *)
  session_global_shapes     : Termcode.Gshape.gshape;
  (* New shapes *)
  session_bound_shape_table : (Termcode.bound_shape) Hpn.t;
  (* Old shapes (mutually exclusive with session_global_shapes and
     session_sum_shape_table_new *)
  session_shape_table       : Termcode.shape Hpn.t;
  session_sum_table         : Termcode.checksum Hpn.t;
}

type session = {
  proofAttempt_table            : proof_attempt_node Hint.t;
  mutable next_proofAttemptID   : int;
  proofNode_table               : proof_node Hint.t;
  mutable next_proofNodeID      : int;
  trans_table                   : transformation_node Hint.t;
  mutable next_transID          : int;
  mutable next_fileID           : int;
  session_dir                   : string; (** Absolute path *)
  session_files                 : file Hfile.t;
  session_prover_ids            : int Hprover.t;
  shapes                        : sshape;
  (* tasks *)
  session_raw_tasks : Task.task Hpn.t;
  session_task_tables : Trans.naming_table Hpn.t;
  (* proved status *)
  file_state: bool Hfile.t;
  th_state: bool Ident.Hid.t;
  tn_state: bool Htn.t;
  pn_state : bool Hpn.t;
}

(* This module handles all session-internal shape/checksum operations *)
module Sshape = struct

  open Termcode

  let add_shape s goal_id shape =
    let sshape = s.shapes in
    match shape with
    | Old_shape shape ->
        Hpn.add sshape.session_shape_table goal_id shape
    | Bound_shape shape ->
        Hpn.add sshape.session_bound_shape_table goal_id shape

  let add_empty_shape s goal_id =
    if is_bound_sum_shape_version s.shapes.shape_version then
      Hpn.add s.shapes.session_bound_shape_table goal_id empty_bound_shape
    else
      Hpn.add s.shapes.session_shape_table goal_id empty_shape

  let get_shape s goal_id =
    if is_bound_sum_shape_version s.shapes.shape_version then
         let shape = try Hpn.find s.shapes.session_bound_shape_table goal_id with
                     | Not_found -> empty_bound_shape in
         Bound_shape shape
       else
         let shape = try Hpn.find s.shapes.session_shape_table goal_id with
                     | Not_found -> empty_shape in
         Old_shape shape

  let compute_and_add_shape s ~expl goal_id t =
    let sshapes = s.shapes in
    let version = sshapes.shape_version in
        if is_bound_sum_shape_version sshapes.shape_version then
         let gs = sshapes.session_global_shapes in
         let shape = Gshape.t_bound_shape_task gs ~version ~expl t in
         Hpn.add sshapes.session_bound_shape_table goal_id shape
       else
         let shape = t_shape_task ~version ~expl t in
         Hpn.add sshapes.session_shape_table goal_id shape

  let find_sum s goal_id =
    try Hpn.find s.shapes.session_sum_table goal_id with
    | Not_found -> Termcode.dumb_checksum

  let add_sum s goal_id sum =
    Hpn.add s.shapes.session_sum_table goal_id sum

  let clear s =
    Gshape.clear_gs s.shapes.session_global_shapes;
    Hpn.clear s.shapes.session_bound_shape_table;
    Hpn.clear s.shapes.session_shape_table;
    Hpn.clear s.shapes.session_sum_table

  let clear_only_shape s =
    Gshape.clear_gs s.shapes.session_global_shapes;
    Hpn.clear s.shapes.session_bound_shape_table;
    Hpn.clear s.shapes.session_shape_table

  let copy_global_shape from_s to_s =
    Termcode.Gshape.copy from_s.session_global_shapes to_s.session_global_shapes

let empty_session ?sum_shape_version ?from dir =
  let prover_ids =
    match from with
    | Some s -> s.session_prover_ids
    | None -> Hprover.create 7
  in
  let version, has_shapes = match sum_shape_version,from with
    | None, None -> Termcode.current_sum_shape_version, false
    | Some v, None -> v, true
    | None, Some s -> s.shapes.shape_version, s.shapes.has_shapes
    | Some _, Some _ ->
       failwith "Session_itp.empty_session: cannot use both optional arguments at the same time"
  in
  let empty_shapes =
    {
      has_shapes;
      shape_version = version;
      session_global_shapes = Termcode.Gshape.create ();
      session_bound_shape_table = Hpn.create 97;
      session_shape_table = Hpn.create 97;
      session_sum_table = Hpn.create 97;
    } in
  (* It is necessary to copy the global_shapes as potentially detached goal
     shape will refer to an old global_shape assignment: we need to propagate it
     An example is: reload with parse error then reload again with different
     source code.
  *)
  (match from with
  | None -> ()
  | Some from -> Sshape.copy_global_shape from.shapes empty_shapes);
  { proofAttempt_table = Hint.create 97;
    next_proofAttemptID = 0;
    proofNode_table = Hint.create 97;
    next_proofNodeID = 0;
    trans_table = Hint.create 97;
    next_transID = 0;
    next_fileID = 0;
    session_dir = dir;
    session_files = Hfile.create 3;
    session_prover_ids = prover_ids;
    shapes = empty_shapes;
    session_raw_tasks = Hpn.create 97;
    session_task_tables = Hpn.create 97;

let save_proof_attempt fmt ((id,tl,sl,ml),a) =
  fprintf fmt
    "@\n@[<h><proof@ prover=\"%i\"%a%a%a%a>"
    id
    (save_float_def "timelimit" tl) (a.limits.Call_provers.limit_time)
    (save_int_def "steplimit" sl) (a.limits.Call_provers.limit_steps)
    (save_int_def "memlimit" ml) (a.limits.Call_provers.limit_mem)
    (save_bool_def "obsolete" false) a.proof_obsolete;
  begin match a.proof_script with
  | None -> ()
  | Some p -> save_file_path fmt p
  end;
  save_status fmt a.proof_state;
  fprintf fmt "</proof>@]"

let save_ident fmt id =
  let n =
    try
      let (_,_,l) = Theory.restore_path id in
      if l = [] then raise Not_found;
      String.concat "." l
    with Not_found -> id.Ident.id_string
  in
  fprintf fmt "name=\"%a\"" save_string n

let rec save_goal s ctxt fmt pnid =
  let pn = get_proofNode s pnid in
  fprintf fmt
    "@\n@[<v 0>@[<h><goal@ %a%a%a>@]"
    save_ident pn.proofn_name
    (save_string_attrib "expl") pn.proofn_expl
    (save_bool_def "proved" false) (pn_proved s pnid);
  let sum = Sshape.find_sum s pnid in
  let shape = Sshape.get_shape s pnid in
  Compress.Compress_z.output_string ctxt.ch_shapes (Termcode.string_of_checksum sum);
  Compress.Compress_z.output_char ctxt.ch_shapes ' ';
  Compress.Compress_z.output_string ctxt.ch_shapes (Termcode.string_of_shape shape);
  Compress.Compress_z.output_char ctxt.ch_shapes '\n';
  let l = Hprover.fold
      (fun _ a acc ->
       let a = get_proof_attempt_node s a in
       (Mprover.find a.prover ctxt.provers, a) :: acc)
      pn.proofn_attempts [] in
  let l = List.sort (fun ((i1,_,_,_),_) ((i2,_,_,_),_) -> compare i1 i2) l in
  List.iter (save_proof_attempt fmt) l;
  let l =
    List.fold_left (fun acc t -> (t,get_transfNode s t) :: acc) [] pn.proofn_transformations
  in
  let l = List.sort (fun (_,t1) (_,t2) ->
                     compare t1.transf_name t2.transf_name) l in
  List.iter (save_trans s ctxt fmt) l;
  fprintf fmt "@]@\n</goal>";

and save_trans s ctxt fmt (tid,t) =
  let arg_id = ref 0 in
  let save_arg fmt s =
    arg_id := !arg_id + 1;
    fprintf fmt "arg%i=\"%a\"" !arg_id save_string s
  in
  fprintf fmt "@\n@[<hov 1>@[<h><transf@ name=\"%a\"%a %a>@]"
    save_string t.transf_name
    (save_bool_def "proved" false) (tn_proved s tid)
    (Pp.print_list Pp.space save_arg) t.transf_args;
  List.iter (save_goal s ctxt fmt) t.transf_subtasks;
  fprintf fmt "@]@\n</transf>"

let save_theory s ctxt fmt t =
  (* Saving empty theories takes space in session files. Not saving them should
     be harmless. *)
  if t.theory_goals <> [] then
  begin
    fprintf fmt
      "@\n@[<v 1>@[<h><theory@ %a%a>@]"
      save_ident t.theory_name
      (save_bool_def "proved" false) (th_proved s t);
    List.iter (save_goal s ctxt fmt) t.theory_goals;
    fprintf fmt "@]@\n</theory>"
  end

let save_file s ctxt fmt _ f =
  fprintf fmt
    "@\n@[<v 0>@[<h><file%a%a>@]@\n%a"
    (save_string_attrib "format") f.file_format
    (save_bool_def "proved" false) (file_proved s f)
    save_file_path f.file_path;
  List.iter (save_theory s ctxt fmt) f.file_theories;
  fprintf fmt "@]@\n</file>"

let save fname shfname session =
  let ch = open_out fname in
  let chsh = Compress.Compress_z.open_out shfname in
  let fmt = formatter_of_out_channel ch in
  fprintf fmt "<?xml version=\"1.0\" encoding=\"UTF-8\"?>@\n";
  fprintf fmt "<!DOCTYPE why3session PUBLIC \"-//Why3//proof session v5//EN\"@ \"https://www.why3.org/why3session.dtd\">@\n";
  fprintf fmt "@[<v 0><why3session shape_version=\"%a\">"
    Termcode.pp_sum_shape_version session.shapes.shape_version;
  let prover_ids = session.session_prover_ids in
  let provers =
    PHprover.fold (get_prover_to_save prover_ids)
      (get_used_provers_with_stats session) Mprover.empty
  in
  let provers_to_save =
    Mprover.fold
      (fun p (id,mostfrequent_timelimit,mostfrequent_steplimit,mostfrequent_memlimit) acc ->
        Mint.add id (p,mostfrequent_timelimit,mostfrequent_steplimit,mostfrequent_memlimit) acc)
      provers Mint.empty
  in
  Mint.iter (save_prover fmt) provers_to_save;
  if Termcode.is_bound_sum_shape_version session.shapes.shape_version then
    begin
      (* In version SV6 or higher, first save the list of variables that are
         referenced in shapes. *)
      let s =
        Format.asprintf
          "(* shapes version: %a *)\n"
          Termcode.pp_sum_shape_version session.shapes.shape_version in
      Compress.Compress_z.output_string chsh s;
      Termcode.Gshape.write_shape_to_file session.shapes.session_global_shapes chsh;
      Compress.Compress_z.output_string chsh "\n";
    end;
  let ctxt = { provers = provers; ch_shapes = chsh } in
  Hfile.iter (save_file session ctxt fmt) session.session_files;
  fprintf fmt "@]@\n</why3session>";
  fprintf fmt "@.";
  close_out ch;
  Compress.Compress_z.close_out chsh


let save_session (s : session) =
  let uniformize_shape () =
    (* When all is detached, don't erase the current shapes to not lose nodes *)
    if not (Hfile.fold (fun _ f b -> is_detached s (AFile f) && b)
              (get_files s) true) then
      begin
        Sshape.clear_only_shape s;
        s.shapes.shape_version <- Termcode.current_sum_shape_version;
        fold_all_session s (fun () any ->
            match any with
            | APn g when not (is_detached s any)  ->
                let t = get_task s g in
                let (_, expl, _) =
                  let root =
                    match get_proof_parent s g with
                    | Trans _ -> false | Theory _ -> true in
                  Termcode.goal_expl_task ~root t in
                Sshape.compute_and_add_shape s ~expl g t;
            | _ -> ()) ()
      end in
  (* Used here so that shape do not save artifacts of the old saved shapes or
     removed goals (making them grow). It also ensures the order of hypothesis
     is deterministic between two runs of Why3. *)
  uniformize_shape ();
  let f = Filename.concat s.session_dir db_filename in
  Sysutil.backup_file f;
  let fs = Filename.concat s.session_dir shape_filename in
  Sysutil.backup_file fs;
  let fz = Filename.concat s.session_dir compressed_shape_filename in
  Sysutil.backup_file fz;
  session_dir_for_save := s.session_dir;
  let fs = if Compress.compression_supported then fz else fs in
  save f fs s

let load_result a (path,acc) r =
  match r.Xml.name with
  | "result" ->
     begin
       match acc with
       | Some _ ->
          Loc.error (LoadError (a,"too many result elements"))
       | None -> ()
     end;
     let status = string_attribute "status" r in
     let answer =
       match status with
       | "valid" -> Call_provers.Valid
       | "invalid" -> Call_provers.Invalid
       | "unknown" -> Call_provers.Unknown ""
       | "timeout" -> Call_provers.Timeout
       | "outofmemory" -> Call_provers.OutOfMemory
       | "failure" -> Call_provers.Failure ""
       | "highfailure" -> Call_provers.HighFailure ""
       | "steplimitexceeded" -> Call_provers.StepLimitExceeded
       | "stepslimitexceeded" -> Call_provers.StepLimitExceeded
       | s ->
          Loc.warning warn_unexpected_session_element "Session.load_result: unexpected status '%s'@." s;
          Call_provers.HighFailure "unexpected result from load_result"
     in
     let time =
       try float_of_string (List.assoc "time" r.Xml.attributes)
       with Not_found -> 0.0
     in
     let steps =
       try int_of_string (List.assoc "steps" r.Xml.attributes)
       with Not_found -> -1
     in
     let res = {
       Call_provers.pr_answer = answer;
       Call_provers.pr_time = time;
       Call_provers.pr_output = "";
       Call_provers.pr_status = Unix.WEXITED 0;
       Call_provers.pr_steps = steps;
       Call_provers.pr_models = [];
       }

let init_subp_vcs c subp =
  apply_split_goal_if_needed c subp.subp_goal

let save_session c =
   Session_itp.save_session c.Controller_itp.controller_session

let mk_subp_goal goal = { subp_goal = goal }

let iter_subps c f =
   let s = c.Controller_itp.controller_session in
   let acc = ref [] in
   let _: unit =
     iter_main_goals s (fun g ->
       let task = Session_itp.get_task s g in
       if task = None then ()
       else acc := mk_subp_goal g :: !acc) in
   List.iter f !acc

let save_session_and_exit c signum =
  (* Ignore all SIGINT, SIGHUP and SIGTERM, which may be received when
     gnatprove is called in GNATStudio, so that the session file is always
     saved. Wrap in exception block as some signals are not supported on
     windows. *)
  begin try
    Sys.set_signal Sys.sigint Sys.Signal_ignore;
    Sys.set_signal Sys.sighup Sys.Signal_ignore;
    Sys.set_signal Sys.sigterm Sys.Signal_ignore;
  with Invalid_argument _ -> () end;
  C.save_session c;
  exit signum

 (* This is the main code. We read the file into the session if not already
    done, we apply the split_goal transformation when needed, and we schedule
    the first VC of all check. When done, we save the session.
 *)

let _ =
  if Gnat_config.debug then Debug.(set_flag (lookup_flag "gnat_ast"));
  Debug.set_flag Pinterp.debug_disable_builtin_mach;
  Debug.set_flag Debug.stats;
  List.iter Introduction.add_unique_prefix
    ["GP_Check:"; "GP_Pretty_Ada:"; "GP_Shape:"; "GP_Sloc:";
     "GP_Already_Proved"; "GP_Inline"; "GP_Inlined"];
  ( try
      let log = Sys.getenv "GNATWHY3LOG" in
      let out = open_out_gen [Open_text; Open_creat; Open_append] 0o666 log in
      let fmt = Format.formatter_of_out_channel out in
      Debug.set_debug_formatter fmt;
      Format.fprintf fmt "@.@.===== %s@." Gnat_config.filename;
      Loc.set_warning_hook (fun ?loc:_ line -> Format.fprintf fmt "%s@." line)
    with Not_found -> () );
  try
    let c = Debug.Stats.record_timing "gnatwhy3.init" Gnat_checks.init_cont in
    (* This has to be done after initialization of controller. Otherwise we
       don't have session. *)
    Sys.set_signal Sys.sigint (Sys.Signal_handle (save_session_and_exit c));
    begin match Gnat_config.proof_mode with
    | Gnat_config.Progressive
    | Gnat_config.Per_Path
    | Gnat_config.Per_Check ->
        Debug.Stats.record_timing "gnatwhy3.register_vcs"
         (fun () -> C.iter_subps c (normal_handle_one_subp c));
        if Gnat_config.replay then begin
          C.replay c (*;
          Gnat_checks.do_scheduled_jobs (fun _ _ -> ());*)
        end else begin
          Debug.Stats.record_timing "gnatwhy3.schedule_vcs"
           (fun () -> Gnat_checks.iter (handle_obj c));
        end;
     | Gnat_config.All_Split ->
        C.iter_subps c (all_split_subp c)
     | Gnat_config.No_WP ->
        (* we should never get here *)
        ()
    end;
    Gnat_scheduler.main_loop (ending c)
  with e when Debug.test_flag Debug.stack_trace -> raise e
  | Out_of_memory as e -> raise e
  | e ->
      let s = Pp.sprintf "%a.@." Exn_printer.exn_printer e in
      Gnat_util.abort_with_message ~internal:true s

let register check check_tree result =
  let valid, extra_info, stats, models, manual, unproved_status =
    match result with
    | Proved (stats, stats_checker) ->
        true,
        {Gnat_expl.pretty_node = None; inlined = None},
        Some (stats, stats_checker),
        [],
        None,
        Gnat_expl.Unknown
    | Not_Proved (extra_info, models, manual, unproved_status) ->
        false, extra_info, None, models, manual, unproved_status
  in
  if (Gnat_expl.HCheck.mem msg_set check) then assert false
  else begin
    let stats_g = Option.map (fun x -> let (stats, _) = x in stats) stats in
    let stats_checker = Option.map (fun x -> let (_, sc) = x in sc) stats in
    let msg =
    { result         = valid;
      extra_info     = extra_info;
      stats          = adapt_stats stats_g;
      stats_checker  = Option.value ~default:0 stats_checker;
      check_tree     = check_tree;
      cntexmp_models = models;
      manual_proof   = manual;
      unproved_status = unproved_status } in
    Gnat_expl.HCheck.add msg_set check msg

let get_msg (check, m) =
  Record (
    List.concat [
      [ "id", Int check.Gnat_expl.id ;
        "check_kind", String (Gnat_expl.check_kind_to_ada check.Gnat_expl.check_kind) ;
        "result", Bool m.result ;
        "check_tree", m.check_tree ;
        "extra_info", get_extra_info m.extra_info ;
        "unproved_status", get_unproved_status m.unproved_status
      ] ;
      get_stats (m.stats, m.stats_checker);
      ["cntexmps", List (get_cntexmp_models m.cntexmp_models)];
      get_manual_proof_info m.manual_proof
    ]
  )

(* In case several models are returned by Why3, we sort them by id. *)
let sort_messages (l : (Gnat_expl.check * msg) list) =
  List.sort (fun x y -> compare (fst x).Gnat_expl.id (fst y).Gnat_expl.id) l

let get_results () =
  let msg_set =
    Gnat_expl.HCheck.fold (fun k v acc -> (k,v) :: acc) msg_set []
  in
  "results", List (List.map get_msg (sort_messages msg_set))

let get_warnings () =
  match !warning_list with
  | [] -> []
  | l -> [("warnings", List (List.map (fun elem -> String elem) l))]

let get_timings () =
  let l = Hashtbl.fold (fun k v acc -> (k,v)::acc) (Debug.Stats.get_timings ()) [] in
  let get_name s = s in
  "timings", Record (List.map (fun (k,(v,_n)) -> get_name k, StandardFloat v) l)

let get_entity () =
  "entity", Int Gnat_config.entity

(* The main function, where we build the final Record to be printed using
Why3.Json_base.print_json function. *)
let print_messages () =
  print_json_single_line Format.std_formatter (
    Record (
      List.concat [
        [get_results (); get_timings (); get_entity ()];
        get_warnings ()
      ]
    )
  )

let abort_with_message ~internal s =
  print_json Format.std_formatter 
    (Record [ "error", String s;
              "internal", Bool internal;
              "results", List []]);
  exit 1

let () =
  Printexc.set_uncaught_exception_handler
    (fun exn raw_backtrace ->
       let bt = Printexc.raw_backtrace_to_string raw_backtrace in
       let msg = Format.asprintf "%a\nBacktrace is the following:\n%s@."
           Why3.Exn_printer.exn_printer exn bt
       in
       let internal =
         match exn with
         | Out_of_memory -> false
         | _ -> true in
       abort_with_message ~internal msg)

let get_timings () = timing_map

let add_timing name time =
  let old_t, old_n =
    try Hashtbl.find timing_map name
    with Not_found -> 0.0, 0 in
  Hashtbl.replace timing_map name (old_t +. time, old_n + 1)

let record_timing name f =
  if test_flag stats then
    let begin_time = Unix.gettimeofday () in
    Fun.protect f
      ~finally:(fun () -> add_timing name (Unix.gettimeofday () -. begin_time))
  else f ()

let backup_file f =
  if Sys.file_exists f then begin
    let fb = f ^ ".bak" in
    if Sys.file_exists fb then Sys.remove fb;
    Sys.rename f fb
  end

let reload_files ?(hard_reload=false) ?reparse_file_fun ~ignore_shapes (c : controller) =
  let old_ses = c.controller_session in
  if hard_reload then begin
    c.controller_env <- Env.create_env (Env.get_loadpath c.controller_env);
    Whyconf.Hprover.reset c.controller_provers;
    load_drivers c;
  end;
  c.controller_session <- empty_session ~from:old_ses (get_dir old_ses);
  (* FIXME: here we should compare [shape_version] with the version of shapes just loaded.
     OR: even better, this function has no reason to have a [shape_version] parameter
     and should always take the version from the file just loaded. *)
  match reparse_file_fun with
  | None ->
      merge_files ~ignore_shapes c.controller_env c.controller_session old_ses
  | Some reparse_file_fun ->
      merge_files_gen ~ignore_shapes ~reparse_file_fun c.controller_env c.controller_session old_ses

exception Errors_list of exn list

let reload_files ?(hard_reload=false) ?reparse_file_fun ~ignore_shapes (c: controller) =
  let errors, b1, b2 = reload_files ~hard_reload ?reparse_file_fun ~ignore_shapes c in
  match errors with
  | [] -> b1, b2
  | _ -> raise (Errors_list errors)

let build_prover_call spa =
  let c = spa.spa_contr in
  let limits = spa.spa_limits in
  let (config_pr,driver) = Hprover.find c.controller_provers spa.spa_pr in
  let with_steps =
    Call_provers.(limits.limit_steps > empty_limits.limit_steps) in
  let command =
    Whyconf.get_complete_command config_pr ~with_steps in
  match Session_itp.get_task c.controller_session spa.spa_id with
  | exception Not_found (* goal has no task, it is detached *) ->
    spa.spa_callback Detached
  | task ->
    Debug.dprintf debug_sched "[build_prover_call] Script file = %a@."
                  (Pp.print_option Pp.string) spa.spa_pr_scr;
    let inplace = config_pr.Whyconf.in_place in
    let interactive = config_pr.Whyconf.interactive in
    let main = Whyconf.get_main c.controller_config in
    try
      let call = Driver.prove_task ?old:spa.spa_pr_scr ~inplace ~command
          ~limits ~interactive ~config:main driver task in
      let pa =
        { tp_id       = spa.spa_id;
          tp_callback = spa.spa_callback;
          tp_started  = false;
          tp_call     = call;
          tp_ores     = spa.spa_ores } in
      Hashtbl.replace prover_tasks_in_progress call pa
    with Sys_error _ as e ->
      spa.spa_callback (InternalFailure e)

module Gshape = struct

  open Wstdlib

  (* [hyp_shape] associate a shape to its index in the file;
     [index_sh] associate an index to a shape;
     [n] is the last shape variable *)
  type gshape = { mutable hyp_shape: int Mstr.t;
                  mutable index_sh: string Mint.t;
                  mutable n: int }

  let create () =
    { hyp_shape = Mstr.empty;
      index_sh = Mint.empty;
      n = 0 }

  let copy from_s to_s =
    to_s.hyp_shape <- from_s.hyp_shape;
    to_s.index_sh <- from_s.index_sh;
    to_s.n <- from_s.n

  let clear_gs gs =
    gs.hyp_shape <- Mstr.empty;
    gs.index_sh <- Mint.empty;
    gs.n <- 0

  let add_shape gs s =
    try Mstr.find s gs.hyp_shape with
    | Not_found ->
        gs.hyp_shape <- Mstr.add s gs.n gs.hyp_shape;
        gs.index_sh  <- Mint.add gs.n s gs.index_sh;
        gs.n <- gs.n + 1;
        gs.n - 1

  let add_and_prepend gs current_shape s : unit =
    (* Do not save empty: could be confused with end of assingments (TODO to be improved)  *)
    if s = "" then () else
      current_shape := add_shape gs s :: !current_shape

  let add_shape_g gs s =
    let (_: int) = add_shape gs s in ()

  let write_shape_to_file s csh =
    Mint.iter (fun _ s -> Compress.Compress_z.output_string csh s;
                Compress.Compress_z.output_string csh "\n")
      s.index_sh

  let goal_and_expl_shapes (gs: gshape) li =
    try
      match li with
      | expl :: goal :: _ ->
          Mint.find expl gs.index_sh ^ Mint.find goal gs.index_sh
      | _ ->
          ""
    with Not_found -> ""

  let t_bound_shape_task gs ~version ~expl t =
    assert (is_bound_sum_shape_version version);
    let current_shape = ref [] in
    Buffer.clear Shape.shape_buffer;
    let pr = Ident.create_ident_printer [] in
    let c = ref (-1) in
    let m = ref Ident.Mid.empty in
    (* All declarations shape *)
    let local_decls =
      let ut = Task.used_symbols (Task.used_theories t) in
      Task.local_decls t ut in
    let open Decl in
    let do_d d =
      match d.d_node with
      | Dparam _ls -> ()
      | Dprop (_, _pr, f) ->
          let sh =
            (try Shape.t_shape ~version pr c m f with Shape.ShapeTooLong -> ());
            Buffer.contents Shape.shape_buffer in
          Buffer.clear Shape.shape_buffer;
          add_and_prepend gs current_shape sh
      | _ -> () in
    List.iter do_d local_decls;
    (* TODO don't save empty shapes as \n as it could be confused with end of assignments *)
    let expl = if expl = "" then "empty_shape" else expl in
    add_and_prepend gs current_shape expl;
    (* The order should be [|shape|] :: [|goal|] :: [|rest of decl|] *)
    !current_shape

procedure Collect_One_Result is
   Pid     : Process_Id;
   Success : Boolean;
   pragma Warnings (Off, Success); --  modified but then not referenced
begin
   Wait_Process (Pid, Success);
   pragma Assert (Pid /= Invalid_Pid);
   declare
      Fn : constant String := Get_Name_String (Output_File_Map (Pid));
   begin
      Parse_Why3_Results (Fn, Timing);
      Delete_File (Fn, Success);
      Output_File_Map.Delete (Pid);

procedure Create_JSON_File
  (Progress : Analysis_Progress; Stop_Reason : Stop_Reason_Type)
is
   FD        : Ada.Text_IO.File_Type;
   File_Name : constant String :=
     Ada.Directories.Compose
       (Name => Unit_Name, Extension => VC_Kinds.SPARK_Suffix);
   Full      : constant JSON_Value := Create_Object;
begin
   Set_Field (Full, "spark", Get_SPARK_JSON);
   Set_Field (Full, "skip_flow_proof", Get_Skip_Flow_And_Proof_JSON);
   Set_Field (Full, "skip_proof", Get_Skip_Proof_JSON);
   Set_Field
     (Full, "progress", Create (Analysis_Progress'Image (Progress)));
   Set_Field
     (Full, "stop_reason", Create (Stop_Reason_Type'Image (Stop_Reason)));
   Set_Field (Full, "warn_error", Create (Warnings_Errors));
   if Progress >= Progress_Flow then
      Set_Field (Full, "flow", Create (Flow_Msgs));
   end if;
   if Progress >= Progress_Proof then
      Set_Field (Full, "pragma_assume", Create (Get_Pragma_Assume_JSON));
      Set_Field (Full, "proof", Create (Proof_Msgs));
   end if;
   Set_Field (Full, "assumptions", Get_Assume_JSON);

   Set_Field (Full, "timings", Timing_History (Timing));
   Set_Field (Full, "entities", Entity_Table);

   Ada.Text_IO.Create (FD, Ada.Text_IO.Out_File, File_Name);
   Ada.Text_IO.Put (FD, GNATCOLL.JSON.Write (Full, Compact => False));
   Ada.Text_IO.Close (FD);

procedure Run_Gnatwhy3 (E : Entity_Id; Filename : String) is
   use Ada.Directories;
   use Ada.Containers;
   Fn        : constant String := Compose (Current_Directory, Filename);
   Old_Dir   : constant String := Current_Directory;
   Why3_Args : String_Lists.List := Gnat2Why_Args.Why3_Args;
   Command   : GNAT.OS_Lib.String_Access :=
     GNAT.OS_Lib.Locate_Exec_On_Path (Why3_Args.First_Element);
begin
   --  Exit gently if gnat2why3 can't be located, for whatever reason,
   --  e.g. when the PATH is wrong in developer setup.

   if Command = null then
      raise Program_Error with "can't locate gnatwhy3";
   end if;

   --  If the maximum is reached, or we are not allowed to run gnatwhy3 in
   --  parallel, we wait for one process to finish first.

   if Output_File_Map.Length = Max_Subprocesses
     or else
       (not Output_File_Map.Is_Empty
        and then not Gnat2Why_Args.Parallel_Why3)
   then
      Collect_One_Result;
   end if;

   Why3_Args.Append ("--entity");
   Why3_Args.Append (Img (E));
   --  Modifying the command line and printing it for debug purposes. We
   --  need to append the file first, then print the debug output, because
   --  this corresponds to the actual command line run, and finally remove
   --  the first argument, which is the executable name.

   Why3_Args.Append (Fn);

   if Gnat2Why_Args.Debug_Mode then
      for Elt of Why3_Args loop
         Ada.Text_IO.Put (Elt);
         Ada.Text_IO.Put (" ");
      end loop;
      Ada.Text_IO.New_Line;
   end if;

   Why3_Args.Delete_First (1);

   Set_Directory (To_String (Gnat2Why_Args.Why3_Dir));

   --  We need to capture stderr of gnatwhy3 output in case of Out_Of_Memory
   --  messages.

   declare
      Args : Argument_List := Call.Argument_List_Of_String_List (Why3_Args);
      Fd   : File_Descriptor;
      Name : Path_Name_Type;
      Pid  : Process_Id;

   begin
      Create_Temp_File (Fd, Name);
      pragma Assert (Fd /= Invalid_FD);
      Pid :=
        GNAT.OS_Lib.Non_Blocking_Spawn
          (Program_Name           => Command.all,
           Args                   => Args,
           Output_File_Descriptor => Fd,
           Err_To_Out             => True);

      --  If spawning fails, for whatever reason, then simply crash

      if Pid = Invalid_Pid then
         raise Program_Error with "can't spawn gnatwhy3";
      end if;

      Output_File_Map.Insert (Pid, Name);
      Close (Fd);

      for Arg of Args loop
         Free (Arg);
      end loop;
   end;
   Set_Directory (Old_Dir);
   Free (Command);

procedure Handle_Error (Msg : String; Internal : Boolean) is
begin
   --  For errors in gnatwhy3 the source code location is meaningless
   Current_Error_Node := Empty;

   if Internal then
      --  The bugbox generated by the Compiler_Abort routine will either
      --  contain a sloc of the last exception (which is useless, because
      --  the last exception happend when the gnatwhy3 process died, and
      --  was expected), or a generic "GCC error". The latter seems less
      --  confusing for the user.

      Compiler_Abort (Msg, From_GCC => True);
   else
      Ada.Text_IO.Put ("gnatprove: ");
      Ada.Text_IO.Put_Line (Msg);
      Exit_Program (E_Fatal);
   end if;

   function Parse_Why3_Prove_Result
     (V : JSON_Value) return Why3_Prove_Result
   is
      E : Extra_Info := (0, Inline_Info'(Inline => False), No_Bound);
   begin
      if Has_Field (V, "extra_info") then
         declare
            Info   : constant Integer :=
              Integer'(Get (Get (V, "extra_info"), "node"));
            Inline : constant Integer :=
              Integer'(Get (Get (V, "extra_info"), "inline"));
         begin
            E := Parse_Extra_Info ((Info, Inline));
         end;
      end if;
      return
        Why3_Prove_Result'
          (Id            => VC_Id (Integer'(Get (Get (V, "id")))),
           Kind          => VC_Kind'Value (Get (Get (V, "check_kind"))),
           Result        => Get (Get (V, "result")),
           EI            => E,
           VC_File       =>
             (if Has_Field (V, "vc_file")
              then Get (Get (V, "vc_file"))
              else Null_Unbounded_String),
           Editor_Cmd    =>
             (if Has_Field (V, "editor_cmd")
              then Get (Get (V, "editor_cmd"))
              else Null_Unbounded_String),
           Stats         =>
             (if Has_Field (V, "stats")
              then From_JSON (Get (V, "stats"))
              else Prover_Stat_Maps.Empty_Map),
           Cntexmps      => Get (V, "cntexmps"),
           Check_Tree    =>
             (if Has_Field (V, "check_tree")
              then Get (V, "check_tree")
              else Create_Object),
           Unproved_Stat =>
             (if Has_Field (V, "unproved_status")
              then From_JSON (Get (V, "unproved_status"))
              else FPA_Unknown_Rec));
   end Parse_Why3_Prove_Result;

   --  Start of processing for Parse_Why3_Results

begin
   Mark_Subprograms_With_No_VC_As_Proved;

   declare
      File    : constant JSON_Value := Read_File_Into_JSON (Fn);
      Results : constant JSON_Array := Get (Get (File, "results"));
   begin
      if Has_Field (File, "error") then
         declare
            Msg      : constant String := Get (Get (File, "error"));
            Internal : constant Boolean :=
              Has_Field (File, "internal")
              and then Get (Get (File, "internal"));
         begin
            Handle_Error (Msg, Internal);
         end;
      end if;
      Subp := Entity_Id (Integer'(Get (File, "entity")));
      if Has_Field (File, "timings") then
         Handle_Timings (Get (File, "timings"));
      end if;

      --  Try to retreive input values from gnattest if they exist

      Parse_Gnattest_Values (Subp);

      for Index in 1 .. Length (Results) loop
         Handle_Result (Get (Results, Index));
      end loop;
      if Has_Field (File, "warnings") then
         declare
            Warnings : constant JSON_Array := Get (Get (File, "warnings"));
         begin
            for Index in 1 .. Length (Warnings) loop

               --  ??? Use some other mechanism to print those messages?

               Ada.Text_IO.Put_Line (Get (Get (Warnings, Index)));
            end loop;
         end;
      end if;
   end;
exception
   when Error : Invalid_JSON_Stream =>
      declare
         Error_Msg : constant String :=
           Ada.Exceptions.Exception_Message (Error);

         OOM_Prefix : constant String := "Fatal error: out of memory";
         --  If there is an "Out of memory" (or OOM) exception in the OCaml
         --  runtime we get this message, possibly followed by extra info.

      begin
         --  If it is an OOM error, then output the prefix alone

         if Head (Error_Msg, OOM_Prefix'Length) = OOM_Prefix then
            Handle_Error (OOM_Prefix, Internal => False);

         --  Otherwise, output gnatwhy3 error as is

         else
            Handle_Error (Error_Msg, Internal => True);
         end if;
      end;
end Parse_Why3_Results;

