procedure Read_Proof
  with Pre => Valid_Path (Report_Name),
    Post => (Runtime => Report_Last <= Report'Length
      and then (if Report_Complete then Report_Read and then not Report_Too_Long),
      Static => (if Report_Complete then
        (if Output_Mode then
           Application_Report_Read_Complete
           and then Silver_Library_Reports.Unbounded_Application_Report_Policy
             (Raw_Application_Report, Application_Kind)
           and then Silver_Library_Reports.Application_Report_Policy
             (Report (1 .. Report_Last), Application_Kind)
         else Silver_Reports.Recognizes_Null_Report (Report (1 .. Report_Last)))))
is
begin
   Application_Report_Read_Complete := False;
   Raw_Application_Report := Silver_Report_Reader.Model.Byte_Sequences.Empty_Sequence;
   if Output_Mode then
      Silver_Report_Reader.Read_Report
        (Report_Name, Report, Report_Last, Report_Too_Long, Report_Read);
   else
      --  The null recognizer has its own raw-text policy.
      Read_File (Report_Name, Report, Report_Last, Report_Too_Long, Report_Read);
   end if;
   Report_Complete := False;
   if Report_Read and then not Report_Too_Long then
      if Output_Mode then
         Silver_Report_Projection_Audit.Application
           (Silver_Report_Reader.Raw_Bytes, Silver_Report_Reader.Projected_Bytes,
            Silver_Report_Reader.Report_State, Report, Report_Last, Application_Kind);
         Raw_Application_Report := Silver_Report_Reader.Raw_Bytes;
         Application_Report_Read_Complete :=
           Silver_Report_Reader.Report_Ended and then Silver_Report_Reader.Report_Closed;
      end if;
      Report_Complete := (if Output_Mode then
        Silver_Library_Reports.Complete_Application_Proof
          (Report (1 .. Report_Last), Application_Kind)
       else Silver_Reports.Complete_Null_Proof (Report (1 .. Report_Last)));
   end if;
end Read_Proof;

procedure Prove
  with Pre => (Runtime => Valid_Command (Proof_Command),
    Static => Source_Written and then Initial_Source_Matched and then Project_Written
      and then (if Output_Mode then Initial_Libraries_Matched)),
    Post => (Static => Proof_Returned_Success = Success
      and then (if Success then Proof_Command_Matched))
is
begin
   Execute (Proof_Command, Success);
   Proof_Returned_Success := Success;
   Proof_Command_Matched := Success
     and then Command_Text (1 .. Command_Length) = Proof_Command
     and then Interfaces.C."=" (Command_Status, 0);
end Prove;

Prove;
if not Success then
   Failure ("Verification failure for admitted Silver: toolchain or implementation defect.");
   return;
end if;
Read_Proof;
if not Report_Read or else Report_Too_Long then
   Failure ("Verification failure for admitted Silver: missing or incomplete proof evidence.");
   return;
end if;
if not Report_Complete then
   Failure ("Verification failure for admitted Silver: missing or incomplete proof evidence.");
   return;
end if;
if Output_Mode then
   Silver_Libraries.Check_Proof_Evidence (Directory, Runtime_Evidence_Complete);
   if not Runtime_Evidence_Complete then
      Failure ("Verification failure for admitted Silver: missing or incomplete runtime library evidence.");
      return;
   end if;
   Silver_Libraries.Same_Sources (Directory, Library_Sources, Success);
   --  Same_Sources' successful-return contract establishes exact equality.
   Proof_Libraries_Matched := Success
     and then Silver_Libraries.Same_Bytes
       (Silver_Libraries.Checked, Library_Sources)
     and then Silver_Libraries.Bound_To_Compiler (Library_Sources);
   if not Success then
      Failure ("Infrastructure error: runtime library changed during verification.");
      return;
   end if;
end if;
Same_Source (Snapshot, Source, Observed, Observed_Last, Success);
Proof_Source_Matched := Success
  and then Observed (1 .. Observed_Last) = Source;
if not Success then
   Failure ("Infrastructure error: source changed during verification.");
   return;
end if;
Build;

procedure Check_Proof_Evidence (Directory : String; Success : out Boolean) is
   Report : String (1 .. Silver_Library_Reports.Max_Runtime_Report_Length);
   Last : Natural;
   Too_Long, Read_Success : Boolean;
begin
   Success := False;
   Proof_Complete := False;
   Accepted_Reports := (others => False);
   Raw_Reports := (others => Silver_Report_Reader.Model.Byte_Sequences.Empty_Sequence);
   for Kind in Silver_Library_Reports.Report_Kind loop
      pragma Loop_Invariant (Static =>
        (for all Earlier in Silver_Library_Reports.Report_Kind =>
          (if Earlier < Kind then Accepted_Reports (Earlier)
            and then Silver_Library_Reports.Unbounded_Runtime_Report_Policy
              (Raw_Reports (Earlier), Earlier))));
      declare
         Name : constant String := Directory & "/obj/gnatprove/" &
           (case Kind is
              when Silver_Library_Reports.Library_Body => "silver_io.spark",
              when Silver_Library_Reports.Imported_Interface => "silver_output_libc.spark",
              when Silver_Library_Reports.Arguments_Body => "silver_arguments.spark",
              when Silver_Library_Reports.Runtime_Interface => "silver_runtime.spark");
         Accepted : Boolean;
      begin
         Silver_Report_Reader.Read_Report (Name, Report, Last, Too_Long, Read_Success);
         if not Read_Success or else Too_Long then
            return;
         end if;
         Silver_Report_Projection_Audit.Runtime
           (Silver_Report_Reader.Raw_Bytes, Silver_Report_Reader.Projected_Bytes,
            Silver_Report_Reader.Report_State, Report, Last, Kind);
         Raw_Reports (Kind) := Silver_Report_Reader.Raw_Bytes;
         Accepted := Silver_Library_Reports.Complete_Runtime_Proof (Report (1 .. Last), Kind);
         Accepted_Reports (Kind) := Read_Success and then not Too_Long
           and then Silver_Report_Reader.Report_Ended and then Silver_Report_Reader.Report_Closed
           and then Accepted;
         if not Accepted then
            return;

function Native (Replacement, Added_Proof_Directory : String) return Boolean
  with Side_Effects, Always_Terminates => False,
    Pre => Count <= Natural'Last - 2
    and then Valid_Argument (Replacement)
    and then Valid_Argument (Added_Proof_Directory)
    and then (if Replacement'Length /= 0 then Count > 0)
is
   Extra : constant Natural := (if Added_Proof_Directory'Length = 0 then 0 else 2);
   Args : Argument_List_Access := new Argument_List (1 .. Count + Extra);
   Status : Integer;
begin
   for Index in 1 .. Count loop
      pragma Loop_Invariant
        (for all Previous in 1 .. Index - 1 =>
          Args (Previous) /= null and then Valid_Argument (Args (Previous).all));
      pragma Loop_Invariant
        (Static => (for all Previous in 1 .. Index - 1 =>
          Args (Previous) /= null and then Args (Previous).all =
            (if Previous = Count and then Replacement'Length /= 0
             then Replacement else Argument (Previous))));
      declare
         Item : constant String := Argument (Index);
      begin
         if not Valid_Argument (Item) then
            Free_List (Args);
            pragma Assert (Args = null);
            Failure (Invalid_Argument);
            return False;
         end if;
         Args (Index) := new String'
           (if Index = Count and then Replacement'Length /= 0 then Replacement else Item);
      end;
   end loop;
   if Extra = 2 then
      Args (Count + 1) := new String'("--proof-dir");
      Args (Count + 2) := new String'(Added_Proof_Directory);
   end if;
   if not Valid_Path (Silver_Image_Config.Native_Gnatwhy3) then
      Free_List (Args);
      pragma Assert (Args = null);
      Failure (Invalid_Native_Path);
      return False;
   end if;
   pragma Assert
     (Static => Args'First = 1 and then Args'Last = Count + Extra
      and then (for all Index in 1 .. Count => Args (Index) /= null
        and then Args (Index).all =
          (if Index = Count and then Replacement'Length /= 0
           then Replacement else Argument (Index)))
      and then (if Extra = 2 then
        Args (Count + 1) /= null and then Args (Count + 1).all = "--proof-dir"
        and then Args (Count + 2) /= null
        and then Args (Count + 2).all = Added_Proof_Directory));
   Status := Spawn (Silver_Image_Config.Native_Gnatwhy3, Args.all);
   Free_List (Args);
   pragma Assert (Args = null);
   if Status in 0 .. 255 then
      Set_Exit_Status (Ada.Command_Line.Exit_Status (Status));
      return Status = 0;
   else
      Failure (Native_Spawn);
      return False;
   end if;
end Native;
